-- Enable RLS on all application tables.
alter table public.profiles enable row level security;
alter table public.packages enable row level security;
alter table public.food_categories enable row level security;
alter table public.food_items enable row level security;
alter table public.package_categories enable row level security;
alter table public.package_food_items enable row level security;
alter table public.food_alternatives enable row level security;
alter table public.additional_services enable row level security;
alter table public.bookings enable row level security;
alter table public.booking_food_items enable row level security;
alter table public.booking_services enable row level security;
alter table public.booking_status_history enable row level security;
alter table public.availability enable row level security;
alter table public.business_settings enable row level security;

create policy "profiles read self or admin" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "profiles update self or admin" on public.profiles for update using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin());
create policy "public read active packages" on public.packages for select using(is_active or public.is_admin());
create policy "admin manage packages" on public.packages for all using(public.is_admin()) with check(public.is_admin());
create policy "public read active categories" on public.food_categories for select using(is_active or public.is_admin());
create policy "admin manage categories" on public.food_categories for all using(public.is_admin()) with check(public.is_admin());
create policy "public read available food" on public.food_items for select using(is_available or public.is_admin());
create policy "admin manage food" on public.food_items for all using(public.is_admin()) with check(public.is_admin());
create policy "public read package categories" on public.package_categories for select using(true);
create policy "admin manage package categories" on public.package_categories for all using(public.is_admin()) with check(public.is_admin());
create policy "public read package foods" on public.package_food_items for select using(true);
create policy "admin manage package foods" on public.package_food_items for all using(public.is_admin()) with check(public.is_admin());
create policy "public read alternatives" on public.food_alternatives for select using(true);
create policy "admin manage alternatives" on public.food_alternatives for all using(public.is_admin()) with check(public.is_admin());
create policy "public read active services" on public.additional_services for select using(is_active or public.is_admin());
create policy "admin manage services" on public.additional_services for all using(public.is_admin()) with check(public.is_admin());
create policy "customer read own bookings" on public.bookings for select using(customer_id=auth.uid() or public.is_admin());
create policy "customer create own booking" on public.bookings for insert with check(customer_id=auth.uid() and status='pending');
create policy "admin update bookings" on public.bookings for update using(public.is_admin()) with check(public.is_admin());
create policy "customer read own booking food" on public.booking_food_items for select using(exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=auth.uid() or public.is_admin())));
create policy "customer add own booking food" on public.booking_food_items for insert with check(exists(select 1 from public.bookings b where b.id=booking_id and b.customer_id=auth.uid() and b.status='pending'));
create policy "admin manage booking food" on public.booking_food_items for all using(public.is_admin()) with check(public.is_admin());
create policy "customer read own booking services" on public.booking_services for select using(exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=auth.uid() or public.is_admin())));
create policy "customer add own booking services" on public.booking_services for insert with check(exists(select 1 from public.bookings b where b.id=booking_id and b.customer_id=auth.uid()));
create policy "admin manage booking services" on public.booking_services for all using(public.is_admin()) with check(public.is_admin());
create policy "customer read own status history" on public.booking_status_history for select using(exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=auth.uid() or public.is_admin())));
create policy "admin read availability" on public.availability for select using(true);
create policy "admin manage availability" on public.availability for all using(public.is_admin()) with check(public.is_admin());
create policy "public read public settings" on public.business_settings for select using(key in ('business_profile','public_contact','booking_rules'));
create policy "admin manage settings" on public.business_settings for all using(public.is_admin()) with check(public.is_admin());
